<!--vbase-->
<template>
  <div class="container">
    <div class="row q-pt-sm q-pb-sm justify-between items-center">
      <div>
        <FilterBadges
          v-if="tableRef?.columnFilter?.hasActiveFilters?.value"
          :filters="tableRef?.columnFilter?.activeFilters?.value || []"
          :columns="columns"
          @remove="(col) => tableRef?.columnFilter?.clearFilter(col)"
        />
      </div>
      <f-btn
        icon="add"
        :label="$t('new')"
        @click="
          display_create_dialog = true;
          documentStatusAlertObj = {};
        "
      />
    </div>
    <div class="full-width">
      <q-splitter
        :horizontal="!notificationLogOpen"
        :limits="[0, 100]"
        :disable="!notificationLogOpen"
        v-model="splitterModel"
        class="dashboard-main"
        after-class="q-px-sm"
        before-class="q-pa-sm"
        separator-class="q-ma-sm"
      >
        <template v-slot:before>
          <DocBitsTable
            ref="tableRef"
            :rows="rows || []"
            :columns="columns"
            :loading="processing"
            row-key="id"
            table-id="email_notification_table"
            table-height="100%"
            :features="{
              sorting: true,
              clientSideSort: true,
              filtering: true,
              selection: false,
              bulkActions: false,
              rowActions: true,
              resizable: false,
              pagination: false,
              columnReorder: true,
              columnSettings: false,
              stickyFirstColumn: false,
              stickyLastColumn: true,
            }"
            :row-actions="rowActions"
            :column-order="columnOrder"
            no-data-label="no_record_found"
            flat-style
            @row-action="handleRowAction"
            @row-click="handleRowClick"
            @column-reorder="handleColumnReorder"
          >
              <!-- Name column with active/inactive badge -->
              <template #body-cell-name="{ row }">
                <div class="row items-center justify-between no-wrap full-width">
                  <span>{{ row.name }}</span>
                  <q-badge
                    transparent
                    align="middle"
                    :color="row.is_active ? 'green' : 'red'"
                  >
                    {{ row.is_active ? $t('active') : $t('inactive') }}
                  </q-badge>
                </div>
              </template>

              <!-- Document type column -->
              <template #body-cell-doctype="{ row }">
                {{ getDocTypeLabel(row) }}
              </template>

              <!-- Document status column -->
              <template #body-cell-doc_status="{ row }">
                {{ getLabelTranslation(row.doc_status) }}
              </template>

              <!-- Priority column -->
              <template #body-cell-priority="{ row }">
                {{ getLabelTranslation(row.priority) }}
              </template>

              <!-- Time delay column -->
              <template #body-cell-time_delay="{ row }">
                {{ row.delay_delta + ' ' + getLabelTranslation(row.delay_delta_type) }}
              </template>

              <!-- Email to column -->
              <template #body-cell-email_to="{ row }">
                {{ getAssignedUser(row.email_address) }}
              </template>

              <!-- Last modified by column -->
              <template #body-cell-last_modified_by="{ row }">
                {{ getUserName(row.last_modified_by) }}
              </template>

              <!-- Last modified column -->
              <template #body-cell-last_modified_at="{ row }">
                {{ row.last_modified_on ? formatDateAccordingToPreference(row.last_modified_on) : formatDateAccordingToPreference(row.created_on) }}
              </template>
            </DocBitsTable>
        </template>

        <template v-slot:separator>
          <q-btn
            v-if="notificationLogOpen"
            :disable="!notificationLogOpen"
            round
            unelevated
            size="xs"
            icon="close"
            class="panel-expand-button highlighted-back z-index-1"
            @click="closeStatusAlertLogSplitter()"
          />
        </template>

        <template v-slot:after>
          <div v-show="notificationLogOpen">
            <DocStatusAlertLogs
              @closeStatusAlertLog="closeStatusAlertLogSplitter()"
              :alert_id="selectedAlertIdLog"
            />
          </div>
        </template>
      </q-splitter>
    </div>
  </div>

  <q-dialog v-model="delete_confirm" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
        />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          v-close-popup
          @click="deleteRow()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog
    v-model="display_create_dialog"
    persistent
    @keydown.esc="display_create_dialog = false"
  >
    <Create
      :doc_type_list="doc_type_list"
      :documentStatusAlertObj="documentStatusAlertObj"
    ></Create>
  </q-dialog>

  <q-inner-loading :showing="processing" class="index">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import Create from './Create.vue';
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import { CONSTANTS } from 'src/constants';
import { defineComponent, ref, computed } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import Loader from 'src/components/Loader.vue';
import documentUtil from 'src/utils/documentUtil';
import dateUtils from 'src/utils/date';
import { useDropdownStore } from 'src/store/main';
import { docStatusNotificationsApiService } from 'src/services';
import DocStatusAlertLogs from 'src/pages/Settings/DocStatusNotifications/DocStatusAlertLogs.vue';
import { DocBitsTable, FilterBadges } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';

export default defineComponent({
  el: '#app',
  mixins: [documentUtil, cache, dateUtils],
  components: {
    Create,
    Loader,
    DocStatusAlertLogs,
    DocBitsTable,
    FilterBadges,
  },
  data() {
    return {
      dialog: false,
      documentStatusAlertObj: ref({}),
      splitterModel: ref(100),
      notificationLogOpen: ref(false),
    };
  },
  mounted() {
    this.initView();
    this.loadColumnOrder();

    document.addEventListener('row_added_update', this.rowAddOrUpdate);
    document.addEventListener(
      'update_current_user_orgs',
      this.updateCurrentUserOrganizations,
    );
  },
  unmounted() {
    this.initView();
    document.removeEventListener('row_added_update', this.rowAddOrUpdate);
    document.removeEventListener(
      'update_current_user_orgs',
      this.updateCurrentUserOrganizations,
    );
  },
  methods: {
    sendBack(event: any) {
      if (event.key === 'Escape') {
        this.$router.go(-1);
      }
    },
    async initView() {
      try {
        this.processing = true;
        await this.prepareUsersDropdown();
        await this.getList();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    loadColumnOrder() {
      const savedOrder = this.getDataByKey(
        CONSTANTS.email_notification_columns_order,
      ) as string;
      if (savedOrder) {
        this.columnOrder = JSON.parse(savedOrder);
      }
    },
    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      this.setDataToLocalStorage(
        CONSTANTS.email_notification_columns_order,
        JSON.stringify(newOrder),
      );
    },
    handleRowAction(payload: RowActionPayload) {
      const row = payload.row;
      if (payload.action === 'edit') {
        this.openEditForm(row);
      } else if (payload.action === 'activate' || payload.action === 'deactivate') {
        this.activeDocumentStatusAlert(row);
      } else if (payload.action === 'view_logs') {
        this.openNotificationsLogs(row.id);
      } else if (payload.action === 'delete') {
        this.delete_id = row.id;
        this.delete_confirm = true;
      }
    },
    handleRowClick(payload: { row: any }) {
      this.openEditForm(payload.row);
    },
    rowAddOrUpdate(e: any) {
      if (!e || !e.detail || !e.detail.data) {
        return;
      }
      this.display_create_dialog = false;
      this.documentStatusAlertObj = {};

      if (e.detail.isUpdateMode) {
        this.updateRow(e.detail.data);
      } else {
        this.addNewRow(e.detail.data);
      }
    },

    async deleteRow() {
      try {
        if (!this.delete_id) {
          return;
        }
        this.processing = true;
        await docStatusNotificationsApiService.delete(this.delete_id);

        let delete_index = -1;
        this.rows.forEach((row: any, index: any) => {
          if (row['id'] === this.delete_id) {
            delete_index = index;
          }
        });

        if (delete_index !== -1) {
          this.rows.splice(delete_index, 1);
        }

        this.delete_id = '';
        notify.success(this.$t('email_notification_deleted_success'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    openNotificationsLogs(alert_id: string) {
      const selectedRow = document.getElementById(
        'row_' + alert_id,
      ) as HTMLElement;
      if (this.selectedAlertIdLog) {
        const oldSelectedRow = document.getElementById(
          'row_' + this.selectedAlertIdLog,
        ) as HTMLElement;
        if (oldSelectedRow) {
          oldSelectedRow.classList.remove('light-grey-with-effect');
        }
      }
      this.selectedAlertIdLog = alert_id;
      this.notificationLogOpen = true;
      this.splitterModel = 60;
      if (selectedRow) {
        selectedRow.classList.add('light-grey-with-effect');
      }
      return;
    },
    closeStatusAlertLogSplitter() {
      this.notificationLogOpen = false;
      this.splitterModel = 100;

      if (this.selectedAlertIdLog) {
        const oldSelectedRow = document.getElementById(
          'row_' + this.selectedAlertIdLog,
        ) as HTMLElement;
        if (oldSelectedRow) {
          oldSelectedRow.classList.remove('light-grey-with-effect');
        }
      }
    },
    openEditForm(rowObj: any) {
      this.documentStatusAlertObj = { ...rowObj };
      this.display_create_dialog = true;
    },

    async getList() {
      const response = await docStatusNotificationsApiService.getAll();
      if (!response) {
        return;
      }

      this.rows = [] as any;
      this.rows = response;
    },

    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      newRow['document_title'] = newRow['doc_type_key'];
      newRow['document_translation_key'] = newRow['doc_type_key'];
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },
    updateRow(updatedRow: any) {
      this.rows
        .filter((row: any) => row.id === updatedRow.id)
        .map((row: any) => {
          row.name = updatedRow.name;
          row.doc_status = updatedRow.doc_status;
          row.priority = updatedRow.priority;
          row.doc_type_key = updatedRow.doc_type_key;
          row.email_address = updatedRow.email_address;
          row.document_title = updatedRow.document_title
            ? updatedRow.document_title
            : updatedRow.doc_type_key;
          row.email_template_id = updatedRow.email_template_id;
          row.delay_delta = updatedRow.delay_delta;
          row.delay_delta_type = updatedRow.delay_delta_type;
          row.is_recursive = updatedRow.is_recursive;
          row.document_translation_key = updatedRow.document_translation_key
            ? updatedRow.document_translation_key
            : updatedRow.doc_type_key;
          row.send_to_assigned_user = updatedRow.send_to_assigned_user;
          row.resend_on_assignee_change = updatedRow.resend_on_assignee_change;
        });
    },

    getAssignedUser(assignedUser: string) {
      return assignedUser ? assignedUser : this.$t('assigned_user');
    },

    getDocTypeLabel(row: any) {
      let label = row['document_title'] || '';

      if (!row['doc_type_key']) {
        return String(label);
      }

      this.doc_type_list.forEach((docType: any) => {
        if (docType.value === row['doc_type_key']) {
          label = docType.label;
        }
      });

      return String(label);
    },

    getUserName(userId: string): string {
      if (!userId) return '-';
      const user = this.usersMap.get(Number(userId));
      if (user) {
        return `${user.first_name} ${user.last_name}`;
      }
      return userId;
    },

    async activeDocumentStatusAlert(row: any) {
      try {
        this.processing = true;
        const formData = new FormData();
        formData.append('id', String(row.id));
        formData.append('status', String(!row.is_active));
        await docStatusNotificationsApiService.activeDocumentAlertStatus(
          formData,
        );
        notify.success(this.$t('email_notification_updated_success'));
      } catch (err) {
        logError(err);
      } finally {
        this.initView();
        this.processing = false;
      }
    },
  },
  setup() {
    const { t } = useTranslate();
    const dropdown_store = useDropdownStore();
    const { doc_type_list, usersMap } = storeToRefs(dropdown_store);
    const { prepareUsersDropdown } = dropdown_store;

    // Column definitions for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'name',
        label: t.value('name'),
        field: 'name',
        sortable: true,
        align: 'left',
      },
      {
        name: 'doctype',
        label: t.value('document_type'),
        field: 'doc_type_key',
        sortable: true,
        align: 'left',
      },
      {
        name: 'doc_status',
        label: t.value('doc_status'),
        field: 'doc_status',
        sortable: true,
        align: 'left',
      },
      {
        name: 'priority',
        label: t.value('priority'),
        field: 'priority',
        sortable: true,
        align: 'left',
      },
      {
        name: 'time_delay',
        label: t.value('time_delay'),
        field: 'delay_delta',
        sortable: true,
        align: 'left',
      },
      {
        name: 'email_to',
        label: t.value('email_to'),
        field: 'email_address',
        sortable: true,
        align: 'left',
      },
      {
        name: 'last_modified_by',
        label: t.value('last_modified_by'),
        field: 'last_modified_by',
        sortable: true,
        align: 'left',
        style: 'width: 150px',
        filter: false,
      },
      {
        name: 'last_modified_at',
        label: t.value('last_modified_at'),
        field: (row: any) => row.last_modified_on || row.created_on,
        sortable: true,
        align: 'left',
        style: 'width: 150px',
        filter: false,
      },
    ]);

    // Row actions
    const rowActions: RowActionItem[] = [
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
        color: 'primary',
      },
      {
        key: 'deactivate',
        label: 'deactivate',
        icon: 'power_settings_new',
        color: 'primary',
        separator: true,
        show: (row: any) => row.is_active === true,
      },
      {
        key: 'activate',
        label: 'activate',
        icon: 'power_settings_new',
        color: 'primary',
        separator: true,
        show: (row: any) => row.is_active === false,
      },
      {
        key: 'view_logs',
        label: 'email_notification_logs',
        icon: 'history',
        color: 'primary',
        separator: true,
      },
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
      },
    ];

    // Template ref to access table's filter state
    const tableRef = ref<InstanceType<typeof DocBitsTable> | null>(null);

    return {
      doc_type_list,
      display_users_dialog: ref(false),
      display_create_dialog: ref(false),
      selectedId: ref(''),
      selectedName: ref(''),
      columns,
      rows: ref([] as any),
      delete_confirm: ref(false),
      delete_id: ref(''),
      processing: ref(false),
      selectedAlertIdLog: ref(''),
      rowActions,
      columnOrder: ref<string[]>([]),
      tableRef,
      usersMap,
      prepareUsersDropdown,
      t,
    };
  },
});
</script>

<style lang="scss" scoped>
