<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{
            $t('doc_status_notifications_desc')
          }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="
                'full-width ' +
                (new_model['validate_error'] || new_model['required_error']
                  ? 'column-error-border'
                  : '')
              "
              v-model="new_model['name']"
              :label="$t('name')"
              :hint="message"
            >
              <template v-slot:append>
                <q-icon
                  v-if="
                    new_model['validate_error'] || new_model['required_error']
                  "
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['validate_error']">
                      {{ message }}
                    </template>
                    <template v-if="new_model['required_error']">
                      {{ $t('FIELD_REQUIRED') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              outlined
              clearable
              v-model="new_model['doc_type_key']"
              @update:model-value="fetchEmailTemplates"
              :options="doc_type_list"
              emit-value
              map-options
              :label="$t('document_type')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['doc_type_key_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['required_error']">
                      {{ $t('FIELD_REQUIRED') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              outlined
              clearable
              v-model="new_model['email_template']"
              :disable="!email_template_list.length"
              :options="email_template_list"
              emit-value
              map-options
              :label="$t('select_email_template')"
              :loading="isLoadingEmailTemplate"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['email_template_key_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              outlined
              v-model="new_model['doc_status']"
              :options="doc_status_list"
              emit-value
              map-options
              :label="$t('doc_status')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['doc_status_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['doc_status_error']">
                      Field is Required
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              outlined
              v-model="new_model['priority']"
              :options="priority_list"
              emit-value
              map-options
              :label="$t('priority')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['doc_status_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['doc_status_error']">
                      Field is Required
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="col-sm-4 col-md-4 col-lg-4">
            <q-select
              outlined
              v-model="new_model['time_type']"
              :options="time_list"
              emit-value
              map-options
              :label="$t('time_unit')"
              class="column"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['time_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['time_error']">
                      {{ $t('FIELD_REQUIRED') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>

          <div class="col-sm-4 col-md-4 col-lg-4">
            <q-input
              outlined
              tabindex="0"
              :class="
                'column q-ml-md ' +
                (new_model['time_delay_error'] ? 'column-error-border' : '')
              "
              v-model="new_model['time_delay']"
              type="number"
              :label="$t('time_delay')"
              :hint="$t('minimum_5_minutes')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['time_delay_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['time_delay_error']">
                      {{ $t('FIELD_REQUIRED') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>

              <q-tooltip>{{ $t('minimum_email_send_time') }}</q-tooltip>
            </q-input>
          </div>

          <div class="col-sm-12 col-md-4 col-lg-4 p-t-10">
            <f-toggle size="xs"
              icon="repeat"
              :label="
                new_model['is_recursive']
                  ? $t('repeat_notification_alert')
                  : $t('do_not_repeat_notification_alert')
              "
              color="primary"
              v-model="new_model['is_recursive']"
            />
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-checkbox
              v-model="new_model['send_to_assigned_user']"
              :label="$t('send_to_assigned_user_or_group')"
            />
          </div>
        </div>

        <div
          class="row full-width mb-10 mt-8"
          style="margin-bottom: 20px"
          v-if="!new_model['send_to_assigned_user']"
        >
          <q-input
            outlined
            tabindex="0"
            :class="
              'full-width ' +
              (new_model['email_address_error'] ? 'column-error-border' : '')
            "
            v-model="new_model['email_address']"
            label="Email Address"
          >
            <template v-slot:append>
              <q-icon
                v-if="new_model['email_address_error']"
                flat
                dense
                name="error"
                size="24px"
                color="red"
              >
                <q-tooltip class="bg-red line-error-tooltip">
                  <template v-if="new_model['email_address_error']">
                    {{ $t('FIELD_REQUIRED') }}
                  </template>
                </q-tooltip>
              </q-icon>
            </template>
          </q-input>
        </div>
        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-checkbox
              v-model="new_model['resend_on_assignee_change']"
              :label="$t('resend_on_assignee_change')"
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn :label="$t('cancel')" appearance="cancel" v-close-popup />

        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDropdownStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { onlyNumbersCharactersSpaces } from 'src/utils/general';
import {
  docStatusNotificationsApiService,
  emailTemplateService,
} from 'src/services';
import helperUtil from 'src/utils/helperUtil';
import { ApiExceptions } from 'src/exceptions';
import { TIME_UNIT_MINUTES } from 'src/constants';
import { dynamicObj } from 'pages/assets';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil],
  props: {
    doc_type_list: {
      type: [] as any,
    },
    documentStatusAlertObj: {
      type: Object,
    },
  },
  components: {},
  data() {
    return {
      message: this.$t('only_characters_spaces'),
      email_template_list: [],
    };
  },
  setup() {
    let model = {} as { [k: string]: any };
    const dropdown_store = useDropdownStore();
    const { prepareDocStatusesList, prepareTimeList, preparePriorityList } =
      dropdown_store;
    const { doc_status_list, time_list, priority_list } =
      storeToRefs(dropdown_store);

    return {
      prepareTimeList,
      time_list,
      doc_status_list,
      priority_list,
      preparePriorityList,
      prepareDocStatusesList,
      new_model: ref(model),
      loading: ref(false),
      isLoadingEmailTemplate: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
    this.prepareDocStatusesList();
    this.prepareTimeList();
    this.preparePriorityList();
  },
  methods: {
    async setNewModel() {
      if (this.documentStatusAlertObj && this.documentStatusAlertObj.id) {
        if (this.documentStatusAlertObj.doc_type_key) {
          await this.fetchEmailTemplates(
            this.documentStatusAlertObj.doc_type_key,
          );
        }
        this.new_model['id'] = this.documentStatusAlertObj.id;
        this.new_model['name'] = this.documentStatusAlertObj.name;
        this.new_model['doc_status'] = this.documentStatusAlertObj.doc_status;
        this.new_model['email_template'] =
          this.documentStatusAlertObj.email_template_id;
        this.new_model['priority'] = this.documentStatusAlertObj.priority;
        this.new_model['time_delay'] = this.documentStatusAlertObj.delay_delta;
        this.new_model['is_recursive'] =
          this.documentStatusAlertObj.is_recursive;
        this.new_model['doc_type_key'] =
          this.documentStatusAlertObj.doc_type_key;
        this.new_model['time_type'] =
          this.documentStatusAlertObj.delay_delta_type;
        this.new_model['email_address'] =
          this.documentStatusAlertObj.email_address;
        this.new_model['send_to_assigned_user'] = this.documentStatusAlertObj
          .send_to_assigned_user
          ? true
          : false;
        this.new_model['resend_on_assignee_change'] = this
          .documentStatusAlertObj.resend_on_assignee_change
          ? true
          : false;
      } else {
        this.new_model['id'] = '';
        this.new_model['name'] = '';
        this.new_model['time_type'] = '';
        this.new_model['doc_status'] = '';
        this.new_model['email_template'] = '';
        this.new_model['priority'] = '';
        this.new_model['time_delay'] = '';
        this.new_model['is_recursive'] = false;
        this.new_model['doc_type_key'] = '';
        this.new_model['email_address'] = '';
        this.new_model['send_to_assigned_user'] = false;
        this.new_model['resend_on_assignee_change'] = false;
      }

      this.resetErrors();
    },
    async fetchEmailTemplates(docType: string) {
      this.isLoadingEmailTemplate = true;
      this.email_template_list = []; // Reset list
      this.new_model.email_template = ''; // Reset selected template

      if (!docType) {
        this.isLoadingEmailTemplate = false;
        return; // If no document type is selected, do nothing
      }

      try {
        const response =
          await emailTemplateService.getEmailTemplateListByDocType(docType);
        if (!response?.success) {
          notify.error(ApiExceptions.getErrorMessage(response));
          return;
        }

        this.email_template_list = response.data.map(
          (template: { id: string; name: string }) => ({
            label: template.name,
            value: template.id,
          }),
        );
      } catch (err) {
        notify.error('Error fetching email templates:');
        logError(err);
      } finally {
        this.isLoadingEmailTemplate = false;
      }
    },
    resetErrors() {
      this.new_model['doc_status_error'] = false;
      this.new_model['doc_type_key_error'] = false;
      this.new_model['email_template_key_error'] = false;
      this.new_model['validate_error'] = false;
      this.new_model['required_error'] = false;
      this.new_model['time_error'] = false;
      this.new_model['time_delay_error'] = false;
      this.new_model['email_address_error'] = false;
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      let isUpdate = false;

      if (!/^\d+$/.test(this.new_model['time_delay'])) {
        notify.error(
          this.$t('DELAY_MUST_BE_WHOLE_NUMBER'),
        );
        return;
      }

      if (
        this.new_model['time_type'] != TIME_UNIT_MINUTES &&
        this.new_model['time_delay'] < 1
      ) {
        notify.error(
          this.$t('DELAY_SHOULD_BE_GREATER_THEN_1'),
        );
        return;
      }
      if (
        this.new_model['time_type'] === TIME_UNIT_MINUTES &&
        this.new_model['time_delay'] < 5
      ) {
        notify.error(this.$t('SHOULD_BE_GREATER_THEN_5'));
        return;
      }
      if (
        !this.new_model['send_to_assigned_user'] &&
        !this.validateEmail(this.new_model['email_address'])
      ) {
        notify.error(this.$t('invalid_email'));
        return;
      }

      if (!this.new_model['doc_type_key']) {
        this.new_model['doc_type_key'] = '';
      }

      const data: any = {
        name: this.new_model['name'],
        doc_type_key: this.new_model['doc_type_key'],
        doc_status: this.new_model['doc_status'],
        email_template: this.new_model['email_template'],
        priority: this.new_model['priority'],
        delta_type: this.new_model['time_type'],
        is_recursive: this.new_model['is_recursive'],
        delay_delta_value: String(this.new_model['time_delay']),
        send_to_assigned_user: String(this.new_model['send_to_assigned_user']),
        resend_on_assignee_change: String(
          this.new_model['resend_on_assignee_change'],
        ),
        email_address:
          this.new_model['send_to_assigned_user'] === false
            ? this.new_model['email_address']
            : '',
      };

      if (this.new_model['id'] != '' && this.new_model['id'] != null) {
        data.id = this.new_model['id'];
        isUpdate = true;
      }

      let response;
      try {
        this.showLoading();
        response = await docStatusNotificationsApiService.createOrUpdate(data);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }

      if (!response.id) {
        throw new Error('Failed to create new record');
      }
      this.setNewModel();
      const event = new CustomEvent('row_added_update', {
        detail: { data: response, isUpdateMode: isUpdate },
      });
      document.dispatchEvent(event);

      if (isUpdate) {
        notify.success(this.$t('email_notification_updated_success'));
      } else {
        notify.success(this.$t('email_notification_created_success'));
      }
    },

    validateRow(row: any) {
      let validate = true;
      this.resetErrors();

      if (!row['name'] || row['name'].length == 0) {
        row.required_error = true;
        validate = false;
      }

      if (!onlyNumbersCharactersSpaces(row['name'])) {
        row.validate_error = true;
        validate = false;
      }

      if (!row['doc_status'] || row['doc_status'].length == 0) {
        this.new_model['doc_status_error'] = true;
        validate = false;
      }

      if (!row['time_type'] || row['time_type'].length == 0) {
        this.new_model['time_error'] = true;
        validate = false;
      }

      if (!row['time_delay'] || row['time_delay'].length == 0) {
        row.time_delay_error = true;
        validate = false;
      }

      if (
        !row['send_to_assigned_user'] &&
        (!row['email_address'] || row['email_address'].length == 0)
      ) {
        row.email_address_error = true;
        validate = false;
      }

      return validate;
    },
  },
});
</script>

<style lang="scss" scoped></style>
