                />
                <f-btn
                  appearance="secondary"
                  class="q-mr-sm mt-20 q-mb-md"
                  :label="$t('clear_filters')"
                  @click="clearFilter"
                />
              </div>
            </q-menu>
          </template>
        </q-input>
      </div>
      <div class="q-pa-md col-6 min-width-fit-content">
        <div class="row">
          <q-card
            flat
            bordered
            class="status-count-card status-count-card-primary"
          >
            <q-card-section class="status-count-number">
              {{ total_records }}
            </q-card-section>
            <q-tooltip>
              {{ $t('total') }}
            </q-tooltip>
          </q-card>
          <q-separator :vertical="true" class="mr-10" />
          <q-card flat bordered class="status-count-card status-count-card-red">
            <q-card-section class="status-count-number">
              {{ failed_alerts }}
            </q-card-section>
