          >
            <span v-if="col.name === 'created_on'">
              {{ formatDateAccordingToPreference(col.value) }}
            </span>
            <span v-else-if="col.name === 'status'" class="flex-col-center">
              <q-icon
                v-if="props.row['is_sent'] == true"
                :name="'check_circle'"
                :color="'green'"
                size="sm"
              />
              <q-icon v-else :name="'cancel'" :color="'red'" size="sm" />
            </span>
            <span
              v-else-if="col.name === 'document_name'"
              class="text-primary cursor-pointer"
              @click="rowClick(props.row, false, isMediUser())"
            >
              {{ col.value }}
            </span>
            <span v-else>
              {{ col.value }}
            </span>
          </q-td>
