<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { docStatusNotificationsApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { date } from 'quasar';
import type { QTableColumn } from 'quasar';
import dateUtils from 'src/utils/date';
import { i18n } from 'src/boot/i18n';
import DashboardHelper from 'src/pages/Dashboard/DashboardHelper';
import { useUserStore } from 'src/store/main';
export default defineComponent({
  name: 'DocStatusAlertLogs',
  mixins: [helperUtil, helperMixin, dateUtils, DashboardHelper],
  components: { Loader },
  props: {
    alert_id: {
      type: String,
      default: '',
    },
  },
  watch: {
    async alert_id() {
      this.resetData();
      await this.getLogsForDocumentStatusAlert();
    },
  },
  data() {
    return {};
  },

  async mounted() {
    this.showLoading();
    await this.getLogsForDocumentStatusAlert();
    this.prepareTableRows();
    this.hideLoading();
    (<any>window).vpo = this;
  },

  async unmounted() {
    await this.clearFilter(false);
    await this.clearSearchValue(false);
  },

  methods: {
    formatDate(strDate: string, dateFormat: string) {
      return date.formatDate(strDate, dateFormat);
    },

    prepareTableRows() {
      this.rows = this.logs;
      for (let i = 0; i < this.rows.length; i++) {
        this.rows[i].id = this.rows[i].doc_id; // replace id with doc_id to open document using DashboardHelper
        this.rows[i].status = this.rows[i].doc_status;
        this.rows[i].layout = false;
      }
    },

    async nextPageClicked() {
      try {
        this.showLoading();
        this.calculateOffset();
        await this.getLogsForDocumentStatusAlert();
      } catch (err: any) {
        notify.error(err);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    resetPagination() {
      this.total_pages = 0;
      this.current_page = 1;
      this.total_records = 0;
      this.offset = 0;
    },

    setTotalPages() {
      this.total_pages = Math.ceil(this.total_records / this.page_size);
    },

    calculateOffset() {
      this.offset = this.page_size * (this.current_page - 1);
    },

    async inputSearchValueChanges(new_search_value: string) {
      try {
        this.showLoading();
        this.search_value = new_search_value;
        await this.getLogsForDocumentStatusAlert();
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async clearSearchValue(reload = true) {
      this.search_value = '';
      if (reload) {
        await this.getLogsForDocumentStatusAlert();
      }
    },

    async clearFilter(reload = true) {
      this.sort_direction = { value: 'asc', label: i18n.t('sort_asc') };
      this.sort_by = { value: 'created_on', label: i18n.t('triggered_at') };
      this.filter_status = { value: '', label: i18n.t('') };
      this.startDate = '';
      this.endDate = '';
      if (reload) {
        await this.getLogsForDocumentStatusAlert();
      }
    },

    clearStatus() {
      this.filter_status = { value: '', label: i18n.t('') };
    },

    clearDate(date: string) {
      if (date === 'startDate') {
        this.startDate = '';
      } else if (date === 'endDate') {
        this.endDate = '';
      } else {
        this.startDate = '';
        this.endDate = '';
      }
    },
    async applyFilter() {
      this.resetPagination();
      await this.getLogsForDocumentStatusAlert();
    },

    async getLogsForDocumentStatusAlert() {
      if (!this.alert_id) {
        return;
      }
      try {
        this.showLoading();
        let formdata = {} as dynamicObj;
        formdata['per_site'] = this.page_size;
        formdata['offset'] = this.offset || 0;
        formdata['ignore_pagination'] = false;
        formdata['sort_direction'] = this.sort_direction.value;
        formdata['sort_by'] = this.sort_by.value;
        if (this.filter_status.value) {
          formdata['status'] = this.filter_status.value;
        }
        if (this.search_value.length > 0) {
          // Document id or name
          formdata['keyword'] = this.search_value;
        }
        if (this.startDate.length > 1) {
          formdata['start_date'] = this.startDate;
        }
        if (this.endDate.length > 1) {
          formdata['end_date'] = this.endDate;
        }

        this.doc_status_alert_logs =
          await docStatusNotificationsApiService.getStatusAlertLogsByDocAlertId(
            this.alert_id,
            formdata,
          );
        this.logs = this.doc_status_alert_logs.logs;
        this.total_records = this.doc_status_alert_logs.total;
        this.failed_alerts = this.doc_status_alert_logs.failed_alerts;
        this.success_alerts = this.doc_status_alert_logs.success_alerts;
        this.setTotalPages();
        this.prepareTableRows();
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async resetData(reload = false) {
      await this.clearFilter(reload);
      await this.clearSearchValue(reload);
      this.resetPagination();
      this.logs = [];
      this.expanded = {};
      this.complete_logs = {};
      this.displayed_messages = {};
      this.doc_status_alert_logs = ref({} as dynamicObj);
      this.rows = [];
      this.failed_alerts = 0;
      this.success_alerts = 0;
    },
  },
  setup() {
    const user_store = useUserStore();
    const { isMediUser } = user_store;

    const columns: QTableColumn[] = [
      {
        name: 'document_name',
        required: true,
        label: 'document_name',
        align: 'left',
        field: 'document_name',
        headerClasses: 'table-header-status-alert-logs',
        style: 'width: 40%;',
        headerStyle: ' width: 40%;',
      },
      {
        name: 'created_on',
        required: false,
        label: 'triggered_at',
        align: 'left',
        field: 'created_on',
        headerClasses: 'table-header-status-alert-logs',
      },
      {
        name: 'recipient',
        required: false,
        label: 'recipient',
        align: 'left',
        field: 'recipient',
        headerClasses: 'table-header-status-alert-logs',
      },
      {
        name: 'status',
        required: false,
        label: 'status',
        align: 'center',
        field: 'is_sent',
        style: ' align-items: center; justify-content: center; width: 10%;',
        headerStyle: ' width: 10%;',
        headerClasses: 'table-header-status-alert-logs',
      },
    ];

    return {
      expanded: ref({} as dynamicObj),
      complete_logs: ref({} as dynamicObj),
      displayed_messages: ref({} as dynamicObj),
      columns,
      rows: ref([] as any),
      doc_status_alert_logs: ref({} as dynamicObj),
      logs: ref([] as any),
      current_page: ref(1),
      total_pages: ref(0),
      offset: ref(0),
      page_size: ref(10),
      total_records: ref(0),

      search_value: ref(''),
      startDate: ref(''),
      endDate: ref(''),
      sort_direction: ref({ value: 'asc', label: i18n.t('sort_asc') }),
      sort_direction_options: [
        { label: i18n.t('sort_asc'), value: 'asc' },
        { label: i18n.t('sort_desc'), value: 'desc' },
      ],
      sort_by: ref({ value: 'created_on', label: i18n.t('triggered_at') }),
      sort_by_options: [
        { label: i18n.t('triggered_at'), value: 'created_on' },
        { label: i18n.t('document_name'), value: 'document_name' },
        { label: i18n.t('status'), value: 'status' },
      ],
      filter_status: ref({ value: '', label: '' }),
      status_options: [
        { label: i18n.t('status_sent'), value: 'success' },
        { label: i18n.t('status_failed'), value: 'error' },
      ],
      failed_alerts: ref(0),
      success_alerts: ref(0),
      isMediUser,
    };
  },
});
</script>

